export function drawCabSheen(ctx,night=0){if(!Number.isFinite(ctx.canvas?.width))return;ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.globalCompositeOperation='destination-over';const w=ctx.canvas.width,h=ctx.canvas.height,g=ctx.createLinearGradient(0,0,w,h*.7),a=.065*(1-night*.78);g.addColorStop(0,'rgba(220,240,255,0)');g.addColorStop(.3,`rgba(225,240,255,${a})`);g.addColorStop(.38,'rgba(225,240,255,0)');g.addColorStop(.72,`rgba(235,245,255,${a*.55})`);g.addColorStop(1,'rgba(220,240,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.restore();}
